OLD_PAGE_TITLES = {"Choose Your GATEWAY Card", "Choose Your VR's GATEWAY Card", "Choose Your NEXORA Card"}
OLD_PAGE_SUBTITLES = {"Select the card that best fits your style and professional needs."}


def _icon_for(label):
    key = label.strip().lower()
    for prefix, icon in FEATURE_ICONS.items():
        if key.startswith(prefix):
            return icon
    return ""


def seed_product_details(apps, schema_editor):
    Product = apps.get_model("website_content", "OrderCardProduct")
    Feature = apps.get_model("website_content", "OrderCardProductFeature")
    Image = apps.get_model("website_content", "OrderCardProductImage")
    Offer = apps.get_model("website_content", "OrderCardProductOffer")
    Stage = apps.get_model("website_content", "OrderCardProductTimelineStage")
    Page = apps.get_model("website_content", "OrderCardPageSettings")

    for product in Product.objects.all():
        lines = [line.strip() for line in (product.features or "").splitlines() if line.strip()]
        Feature.objects.bulk_create(
            [Feature(product=product, label=line[:150], icon=_icon_for(line), display_order=i) for i, line in enumerate(lines)]
        )

        if product.image_url:
            # The gallery row takes over the Cloudinary asset.
            Image.objects.create(
                product=product,
                image_url=product.image_url,
                image_public_id=product.image_public_id,
                alt_text=product.name,
                is_primary=True,
            )
            product.image_public_id = ""

        if not product.short_description:
            product.short_description = DESCRIPTIONS.get(product.card_type, product.design)
        heading, description = CUSTOMISATION.get(product.card_type, ("", ""))
        if not product.customisation_heading and not product.customisation_description:
            product.customisation_heading = heading
            product.customisation_description = description
        if product.name == "GATEWAY Custom":
            product.name = "VR's Gateway Custom NFC Card"
        product.save()

        Offer.objects.bulk_create(
            [
                Offer(product=product, label="Buy 1", min_quantity=1, unit_price=product.price, display_order=0, is_active=True),
                Offer(product=product, label="Buy 3", min_quantity=3, unit_price=product.price, display_order=1, is_active=False),
                Offer(product=product, label="Buy 5", min_quantity=5, unit_price=product.price, display_order=2, is_active=False),
            ]
        )
        Stage.objects.bulk_create(
            [
                Stage(product=product, title=title, estimate=estimate, description=desc, icon=icon, display_order=i)
                for i, (title, estimate, desc, icon) in enumerate(TIMELINE)
            ]
        )

    for page in Page.objects.all():
        if page.page_title in OLD_PAGE_TITLES:
            page.page_title = "Choose Your VR's Gateway Card"
        if page.page_subtitle in OLD_PAGE_SUBTITLES:
            page.page_subtitle = "Select the card that fits your business needs."
        page.save()


def restore_features_text(apps, schema_editor):
    """Reverse: put the feature list back into the old newline text field,
    and hand each primary image's asset back to its product."""
    Product = apps.get_model("website_content", "OrderCardProduct")
    for product in Product.objects.all():
        product.features = "\n".join(f.label for f in product.feature_items.order_by("display_order", "id"))
        primary = product.images.filter(is_primary=True).first()
        if primary:
            product.image_url = primary.image_url
            product.image_public_id = primary.image_public_id
        product.save()


